"""Twenty disjoint current whole HE-G9 goals; actual source-bound author inputs."""
from pathlib import Path
from datetime import datetime, timezone
import json, hashlib

D=Path(__file__).resolve().parent
ROOT=D.parents[6]
def read(p): return json.loads(p.read_text())
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def write(name,j):
    p=D/name
    with p.open('x') as f: f.write(json.dumps(j,ensure_ascii=False,indent=2)+'\n')

rows=[
('5f39afac-897c-5ed3-95b5-89ccf66b2532','5.1 printed7–8','Artenvielfalt, Entdeckung und Aussterben unterscheiden; lokale Beobachtung ist keine globale Vollinventur.','Friendly meadow with four clearly different organisms and a fossil/field-guide inset. One new-to-science discovery clue and one extinct lineage symbol, no invented global count. Show species versus individuals without tiny tables.'),
('bdbb1a13-f448-5536-86ab-894805e2f6be','5.2 printed9–10','Säugetierorgane anhand von Bau und Funktion zuordnen.','Friendly dog silhouette with only three clear functional zooms: articulated forelimb for movement, lung for gas exchange, heart for transport. Correctly connected shapes, no giant full-organ chart.'),
('ac69483b-6a77-573d-a7c0-add32bb867e2','5.2 printed9–10','Säugetiermerkmale als bewährte funktionelle Angepasstheiten erläutern, ohne zielgerichteten Erwerb.','Otter beside water with dense fur waterproof-insulating zoom and webbed feet swimming zoom. Keep two main examples, no environmental command arrow creating a trait. Fur traps insulating air, never claim hair conducts sunlight into a bear.'),
('9263ee6c-bf62-531c-bb09-78a4a51b8ed7','5.2 printed9–10','Wirkliches Beobachten, trennscharfes Protokoll und vorsichtige Deutung eines Ethogramms.','Student respectfully observing a calm dog, three timed posture sketches and writing a simple ethogram in a notebook facing the writer. No anthropomorphic dog thoughts or fake numeric experiment result.'),
('bac3e333-d044-559e-8d8e-b8eff4af2b56','5.2 printed9–10','Gemeinsame Abstammung, vererbbare Variation und menschliche Zuchtauswahl unterscheiden.','Small branching lineage from an ancestral wolf population to different domestic dog forms. Breeder selection shown by a neutral magnifying choice cue, no single modern wolf transforming into dog or ladder of progress.'),
('19f806d2-d4e3-5ad4-98a8-1d61bdd81e3d','5.4 printed12','Keimungsbedingungen und tatsächlich verfolgte Wachstumsschritte trennen.','Four coherent bean germination stages with radicle emerging before green shoot, moist substrate, warmth and air icons. Notebook faces observing student. Light is a later growth resource, not universal germination prerequisite; no sealed submerged seed.'),
('892a1d3a-9923-5ac2-affa-f2d5c38e3c54','5.4 printed12','Wurzel-, Spross- und Blattfunktionen als zusammenhängendes Transportsystem erklären.','One friendly flowering plant with below-ground roots, stem and leaves. Large blue water/mineral arrow roots-to-leaves and different orange assimilate arrow from leaves toward sinks; sunlight enters leaves. No nutrient food absorbed from soil.'),
('be06115e-96e8-537e-b18a-313056e6cbe8','5.4 printed12','Blütenbestandteile sowie Bestäubung, Befruchtung und Samenbildung funktionell verbinden.','Clear stylized flower section with visible anther, stigma, style, ovary and ovule. Bee carries pollen to stigma; separate small seed/fruit continuation. Pollen cannot directly become the whole seed; bee never enters ovule.'),
('350c8fab-5f95-5cf0-b8a9-dbc5f425b6fd','5.4 printed12','Wild-/Nutzpflanzen anhand von Nutzungskontext und einfachen Bestimmungsmerkmalen unterscheiden.','Student with field guide observing wild daisy and cultivated bean plot. Magnified leaf and flower features support identification; no edible-food recommendation from appearance, no all wild plants harmful.'),
('7eeb9de9-9a8e-5932-8f60-183367c87d09','6.2 printed14','Vogel- oder Fischmerkmale funktionell an Lebensräume binden; vertieftes Wahlthema kennzeichnen.','Two main matched scenes: bird wing/feather in air and fish streamlined body/gills in water, each with one simple movement cue. Bird/fish is a curriculum choice, not simultaneous mandatory depth. No fins morphing into feathers.'),
('4e12ba43-a58c-5611-8c43-3cc0c8465e33','6.2 printed14','Revier, Balz, Paarung und unterschiedliche Investition in Nachkommen vergleichen.','Side-by-side small bird nest with attentive parents and fish eggs in protected shallow habitat, only a few representative eggs plus subtle many cue. Both strategies have conditions; no all fishes abandon offspring or guaranteed survival.'),
('8e1300bb-14a1-5155-884a-144c88f1c04b','6.2 printed14 bird choice','Leichtbau und Federbau funktionell für Flug und Isolation erklären, ohne alle Vögel flugfähig zu nennen.','Flying bird with two large zooms: lightweight braced bone cross-section, coherent feather vane with barbs. Rounded comic form; correct feathers, no plastic solid feather or completely empty unsupported skeleton.'),
('8a56672b-b662-5bcd-9f43-8ffc4abc4f01','6.2 printed14 fish choice','Stromlinienform, Kiemen und Gasraum-Auftrieb als getrennte Fischfunktionen erklären.','One typical bony fish with clear body contour, water through mouth across red gills to operculum, and small separated internal swim-bladder gas sac. Gill gas exchange through water; no oxygen-air hose directly to bladder or every fish has a bladder.'),
('321ea315-37fe-5f9e-8fa8-dd631bb447c7','6.3 printed15','Reptilienentwicklung mit Vogelentwicklung anhand amniotischer Gemeinsamkeiten und Unterschieden vergleichen.','Two simple amniotic egg cross-sections for lizard and bird, with embryo/yolk/protective envelope. Small direct hatchling continuations: young lizard and chick; no tadpole larva or metamorphosis step in either.'),
('2f462b79-4ebc-5ab5-9e72-91135c5252c7','6.3 printed15','Verhaltensregulation bei Ektothermen einschließlich Umwelt- und Aktivitätsgrenzen beschreiben.','Same lizard choosing sunny rock then shaded shelter; one clear external heat arrow and small thermometer change. Ectothermic is not always cold and shade choice regulates within limits; no internal heater or blanket sleeping-in-cold message.'),
('6faa6c23-00c9-5758-bd98-01825692abb2','6.3 printed15','Infrarot-Wahrnehmung des Grubenorgans mit Sehorgan ergänzend verbinden.','Gentle rattlesnake side head with correctly placed loreal pit between nostril and eye, large zoom and a warm mouse at a distance. Separate dotted thermal-signal cue from ordinary vision cue; no seeing blood or all snakes having identical pit organs.'),
('6e2dae03-9ea9-5466-b93e-13adcfb01245','6.4 printed16','O2-Versorgung eines adulten Frosches über feuchte Haut und Lunge erklären.','Friendly adult frog at pond edge. Blue incoming oxygen cues at moist skin and through mouth-to-lung path; separate outgoing carbon-dioxide cues. Correct frog mouth floor respiratory pump, no external gills on adult or dry waterproof skin.'),
('66967754-3934-58b3-b79e-d0f867dae070','6.4 printed16','Hormonelle Metamorphose-Steuerung aus vorgelegten Versuchsergebnissen deuten.','Tadpole-to-frog sequence with coherent limbs and gradually shortening tail, thyroid/hormone message cue beside a small labelled comparison. Schematic supplied result, no child administering hormones to live animals.'),
('ac7f0a5a-dff6-570b-b0fd-10cb0f33be29','6.4 printed16','Eizahlen und unterschiedliche Brutpflegeformen vergleichen, ohne pauschale Erfolgsregel.','Amphibian contrast: larger water egg clutch with little care versus small carried/guarded clutch. No birds or mammalian nursing, no cross-species continuum claiming all large clutches survive less in every habitat.'),
('06e91b97-e7cc-5698-a854-8a946a4bb7d0','6.5 printed17','Artgerechte Haltung mit Physiologie, Verhalten und Verantwortung auf konkrete Fälle anwenden.','Student planning responsible rabbit care with companion rabbit, roomy secure enriched enclosure, hay/water and refuge. Calm respectful scene, not a decorative tiny cage; no animal pictured as toy or every species needing identical companions.')
]
assert len(rows)==20
canonicalPath=ROOT/'curricula/DE/Gymnasium/canonical/DE_DEU_S_GYM_CANONICAL_BIOLOGIE.de.json'
reportPath=D.parent/'biologie-cellcycle-evolution-two-reviewed-active-integration-root-v1/active-after-two-central.actual.json'
landscape=read(canonicalPath);by={g['id']:g for g in landscape['goals']};subject=next(s for s in read(reportPath)['subjects']if s['subject']=='biologie')
exclude=set(subject['strictCompleteGoalIds']);assert len(exclude)==122
for name in ['biologie-human20-current391-author-v1','biologie-ecology20b-current391-author-v1']:
    exclude.update(g['id']for g in read(D.parent/name/'current20-whole-DEEN-goals.actual.json')['goals'])
ids=[r[0]for r in rows]
assert not(set(ids)&exclude)
assert set(ids)<=set(subject['currentGoalIds'])
goals=[by[i]for i in ids]
assert all(not any(l.get('type')=='goal-visualization'for l in g.get('resourceLinks',[]))for g in goals)
write('current20-whole-DEEN-goals.actual.json',{'artifactKind':'current-twenty-whole-goals-inactive-author-input','landscapeId':landscape['landscapeId'],'goals':goals,'activeWrites':0})
plans=[]
for n,(gid,section,concept,scene)in enumerate(rows,1):
    boundary='HE G9 '+section+'. Actual whole section read; selected bounded goal, no approval of all surrounding methods. '
    if 10<=n<=13:boundary+='6.2 requires either bird or fish in depth; the unchosen class is only briefly compared. These own candidates preserve that curricular choice and claim no universal simultaneous depth. '
    if n in [4,6]:boundary+='The goal requires genuine later observation and recording; synthetic model materials are not evidence that an actual observation has been performed. '
    if n==18:boundary+='Only interpretation of supplied hypothetical results; no live-animal hormone experiment is instructed. '
    plans.append({'ordinal':n,'goalId':gid,'wholeGoal':by[gid],'sourceBoundary':boundary,'conceptAndOperator':concept,'scenePlanEn':scene,'scientificTextChanges':False,'status':'neutral_author_candidate_no_approval','format':{'fileFormat':'PNG','aspectRatio':'approximately16:9','preferredNativePixels':[1672,941],'verifyActualWidths':[360,680],'style':'friendly abstract clear comic consistent with existing goal images','textPolicy':'Only few large indispensable labels, no mandatory small print'},'futureRasterCopyPaths':[f'curricula/DE/Gymnasium/visualizations/biologie/{gid}/{gid}.png',f'app/public/assets/goal-visualizations/biologie/{gid}/{gid}.png',f'backend/src/main/resources/static/assets/goal-visualizations/biologie/{gid}/{gid}.png'],'humanApproval':False,'strictGainClaimed':0})
write('neutral-twenty-current-whole-imageplans.author.json',{'artifactKind':'neutral-flora-fauna20-whole-source-bounded-imageplans','baselineCanonical':{'path':str(canonicalPath.relative_to(ROOT)),'sha256':sha(canonicalPath),'bytes':canonicalPath.stat().st_size},'strictCurrentReport':{'path':str(reportPath.relative_to(ROOT)),'sha256':sha(reportPath),'strictCurrent':122,'denominator':391},'goals':plans,'activeWrites':0,'strictClosuresClaimed':0})
primary=D.parent/'biologie-ecology20-current391-author-v2/primary-inputs'
write('actual-whole-HE-G9-primary-reading.author.receipt.json',{'artifactKind':'actual-whole-flora-fauna20-source-reading-author-receipt','authorRole':'author only; independent scientific review pending','recordedAt':datetime.now(timezone.utc).isoformat(),'officialUrl':'https://kultus.hessen.de/sites/kultus.hessen.de/files/2021-06/g9-biologie.pdf','actualPrimarySha256':sha(primary/'HE-G9-official.pdf'),'actualExtractedReadingSha256':sha(primary/'HE-G9-official.actual-full-reading.txt'),'actualSectionsRead':['Entire5.1 printed7–8','Entire5.2 printed9–10','Entire5.4 printed12','Entire6.2 printed14','Entire6.3 printed15','Entire6.4 printed16','Entire6.5 printed17'],'ownReadingSummary':'5.1 diversity/discovery/extinction.5.2 mammal structure/function/adaptation, genuine ethogram, ancestry/domestication.5.4 germination/growth, organs/transports, flowers/reproduction and plant identification.6.2 bird or fish choice and related reproduction.6.3 amniotic development, ectothermic behavioural thermal regulation and rattlesnake thermal sense.6.4 moist skin/lung exchange, endocrine metamorphosis-result interpretation and egg/care strategies.6.5 physiological/behavioural evidence applied to responsible husbandry.','criticalSourceBoundary':'5.2 historical polar-bear hair light/heat-conductor wording is not propagated as a scientific model; use established insulation and other genuine mammal adaptation examples.6.2 depth is a choice.6.4 optional threats not selected. Observations remain genuine later performance. No approval of whole adjacent source duties from own two cases.','selectedWholeGoalIds':ids,'rawSourceLocalOnly':True,'rawSourceIsPResource':False,'rawFullTextCopiedToOwnDossier':False,'rehydration':'Fetch official URL into local cache; compare actual primary SHA256. Extract with pdftotext -layout and read whole indicated sections; changed source bytes need targeted review.','thirdPartyRights':'Official third-party curriculum, no own license grant or full-text redistribution clearance inferred.','activeWrites':0,'humanApproval':False,'strictClosuresClaimed':0})
print(json.dumps({'selectedCurrentGoals':20,'strictCurrentProtected':122,'disjointHuman20AndEcology20b':True,'actualWholePrimarySections':7,'noExistingImagesReplaced':True,'activeWrites':0}))
